import{_ as i,o as a,c as e,ag as t}from"./chunks/framework.ePeAWSvT.js";const g=JSON.parse('{"title":"欢迎来到 Get 笔记","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":null}'),r={name:"guide/index.md"};function o(n,l,s,d,h,u){return a(),e("div",null,[...l[0]||(l[0]=[t('<h1 id="欢迎来到-get-笔记" tabindex="-1">欢迎来到 Get 笔记 <a class="header-anchor" href="#欢迎来到-get-笔记" aria-label="Permalink to &quot;欢迎来到 Get 笔记&quot;">​</a></h1><p>Get 笔记是一款生长在 AI 时代下的小产品，让记笔记、找笔记、用笔记变得简单。</p><p>一条上班上学路上的语音记录，一张微信聊天截屏，一篇群里分享的文章，一条干货满满的短视频，三五个人的碰头会，一张刚送到的外卖午餐照片，深更半夜的灵感迸发，小学生稚嫩的作文……所有这些，在 Get 笔记里，都快速的帮你留下来。</p><blockquote><p>当你的世界从一粒种子，长成一片森林的时候，你会发现，在 AI 的帮助下，你强得可怕。</p></blockquote><h2 id="get-笔记能干什么" tabindex="-1">Get 笔记能干什么 <a class="header-anchor" href="#get-笔记能干什么" aria-label="Permalink to &quot;Get 笔记能干什么&quot;">​</a></h2><h3 id="🎙️-懒得打字-说出来就行" tabindex="-1">🎙️ 懒得打字？说出来就行！ <a class="header-anchor" href="#🎙️-懒得打字-说出来就行" aria-label="Permalink to &quot;🎙️ 懒得打字？说出来就行！&quot;">​</a></h3><ul><li>想说多久说多久，60分钟随便录</li><li>AI 实时转文字，还帮你自动润色</li><li>支持27种方言，说啥都能识别</li><li>专业词汇不怕错，为你建专属词库</li><li>录到一半有事？暂停一下接着说</li><li>锁屏录音、后台运行，啥也不耽误</li><li>没网也不慌，地铁隧道照样用</li></ul><h3 id="📚-还能这样记笔记" tabindex="-1">📚 还能这样记笔记 <a class="header-anchor" href="#📚-还能这样记笔记" aria-label="Permalink to &quot;📚 还能这样记笔记&quot;">​</a></h3><ul><li>📸 <strong>拍照就能记</strong>：课本、白板、文档，拍完就变文字</li><li>🔗 <strong>链接一键记</strong>：好文章、短视频，转存就变精华</li><li>📄 <strong>文档全能记</strong>：PDF、PPT、Word随手传</li><li>🎥 <strong>直播/博主快速记</strong>：订阅直播/博主，AI帮你记录总结</li><li>🧑‍💻 <strong>线下会议录音</strong>：智能识别多位发言人，会后一键生成会议纪要</li><li>🎙️ <strong>手机内录</strong>：自动捕获手机播放的声音，AI边听边记</li></ul><h3 id="✨-个人知识库" tabindex="-1">✨ 个人知识库 <a class="header-anchor" href="#✨-个人知识库" aria-label="Permalink to &quot;✨ 个人知识库&quot;">​</a></h3><p>从碎片到系统，知识管理一步到位：</p><ul><li>🎥 <strong>直播自动记</strong>：丢个链接，AI帮你听讲座、出纪要，还能全文回看</li><li>📱 <strong>博主轻松追</strong>：订阅抖音/视频号，AI 每天追踪最新重点</li><li>👥 <strong>团队共建库</strong>：支持团队协作，知识共创、共享，高效灵活</li><li>🗂 <strong>多主题随心建</strong>：读书、健身、历史……语音文字图片都能记</li><li>🔍 <strong>一搜就有答案</strong>：AI 帮你把碎片内容变成系统知识</li></ul><h3 id="⚡️-记录灵感-就是这么方便" tabindex="-1">⚡️ 记录灵感，就是这么方便 <a class="header-anchor" href="#⚡️-记录灵感-就是这么方便" aria-label="Permalink to &quot;⚡️ 记录灵感，就是这么方便&quot;">​</a></h3><ul><li>桌面小组件，点一下就能记</li><li>实体按键，按一下就能说（iOS专属）</li><li>Siri指令，叫一声就能用（iOS专属）</li></ul><h3 id="🔍-找知识-更靠谱" tabindex="-1">🔍 找知识，更靠谱 <a class="header-anchor" href="#🔍-找知识-更靠谱" aria-label="Permalink to &quot;🔍 找知识，更靠谱&quot;">​</a></h3><ul><li>AI智能搜索，已接入满血版DeepSeek-R1</li><li>打造高信用知识库，整合个人笔记和优质内容</li><li>优质数据+强大推理模型，才会发挥出最佳效果</li></ul><h3 id="🔄-多端同步-随时随地" tabindex="-1">🔄 多端同步，随时随地 <a class="header-anchor" href="#🔄-多端同步-随时随地" aria-label="Permalink to &quot;🔄 多端同步，随时随地&quot;">​</a></h3><ul><li>手机App记录，电脑上就能查</li><li>网页版编辑，手机上实时改</li><li>微信小程序，打开就能用</li><li>所有设备数据实时同步，不用等</li></ul>',18)])])}const p=i(r,[["render",o]]);export{g as __pageData,p as default};
